// Architecture labels intentionally include both canonical service names and
// short names used inside diagrams. Keep one normalized lookup path so small
// naming differences do not turn a real Azure service into a generic fallback.
const normalizeAzureLabel=(label:string)=>label.toLowerCase().replace(/\([^)]*\)/g, "").replace(/&/g, " and ").replace(/[^a-z0-9]+/g, " ").replace(/\b(formerly|legacy)\b/g, "").replace(/\s+/g, " ").trim();
const normalizedAzureIconFiles:Record<string,string>=Object.fromEntries(Object.entries(azureIconFiles).map(([label,file])=>[normalizeAzureLabel(label),file]));
const iconFileFor=(label:string)=>{
  const exact=azureIconFiles[label]||normalizedAzureIconFiles[normalizeAzureLabel(label)];
  if(exact)return exact;
  const normalized=normalizeAzureLabel(label);
  // Composite architecture labels still resolve to the service that owns the
  // boundary instead of falling back to the generic decorative icon.
  if(/entra|active directory|azure ad/.test(normalized))return "microsoft-entra-id.svg";
  if(/search|semantic ranker|indexer/.test(normalized))return "azure-ai-search.svg";
  if(/foundry|prompt flow|agent service|model deployment|evaluation/.test(normalized))return "microsoft-foundry.svg";
  if(/machine learning|\baml\b|model endpoint|managed endpoint|model registry|pipeline|feature store|ground truth|mlflow/.test(normalized))return "azure-machine-learning.svg";
  if(/databricks|synapse|spark|delta|unity catalog|lakehouse/.test(normalized))return "azure-databricks.svg";
  if(/storage|blob|adls|data lake|queue|table/.test(normalized))return "azure-storage.svg";
  if(/monitor|log analytics|application insights|metric|alert|dashboard/.test(normalized))return "azure-monitor.svg";
  if(/purview/.test(normalized))return "microsoft-purview.svg";
  if(/policy|governance/.test(normalized))return "azure-policy.svg";
  if(/sentinel|defender|security copilot/.test(normalized))return "microsoft-defender-for-cloud.svg";
  if(/function|logic app|api management/.test(normalized))return "azure-functions.svg";
  if(/event grid/.test(normalized))return "event-grid.svg";
  if(/service bus/.test(normalized))return "azure-service-bus.svg";
  if(/iot hub/.test(normalized))return "azure-iot-hub.svg";
  return undefined;
};
const azureWalkthroughFilenameOverrides:Record<string,string[]>={
  "Data Catalog":["azure-data-catalog.webp","data-catalog.webp"],
  "Entra ID":["microsoft-entra-id.webp","entra-id.webp"],
  "Microsoft Entra ID":["microsoft-entra-id.webp","entra-id.webp"],
  "Microsoft Entra ID (formerly Azure AD)":["microsoft-entra-id.webp","entra-id.webp"],
  "HDInsight":["azure-hdinsight.webp","hdinsight.webp"],
  "Data Lake Analytics":["azure-data-lake-analytics.webp","data-lake-analytics.webp"],
  "Event Hubs":["azure-event-hubs.webp","event-hubs.webp"],
  "App Service":["azure-app-service.webp","app-service.webp"],
  "Azure Container Apps":["azure-container-apps.webp","container-apps.webp"],
  "Nutanix Cloud Clusters":["azure-nutanix-cloud-clusters.webp","nutanix-cloud-clusters.webp"],
};
const normalizedAzureWalkthroughOverrides:Record<string,string[]>=Object.fromEntries(Object.entries(azureWalkthroughFilenameOverrides).map(([name,files])=>[normalizeAzureLabel(name),files]));
const walkthroughFilenameVariants=(filename:string)=>{
  const normalized=filename.endsWith(".webp")?filename:filename+".webp";
  const alternate=normalized.startsWith("azure-")?normalized.slice("azure-".length):"azure-"+normalized;
  return [normalized,alternate];
};
export const azureWalkthroughUrls=(service:string)=>{
  const slug=service.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
  const filenames=[...(azureWalkthroughFilenameOverrides[service]||normalizedAzureWalkthroughOverrides[normalizeAzureLabel(service)]||[]),slug+".webp"]
    .flatMap(walkthroughFilenameVariants)
    .filter((filename,index,all)=>all.indexOf(filename)===index);
  return filenames.map(filename=>{
    const path="/azure-certification-walkthroughs/"+filename;
    const configured=assetUrl(path);
    return configured===path?"https://pub-a5e11688cacf4195a0d3c6afe384eb56.r2.dev"+path:configured;
  });
};

const azureIconUrl=(file:string)=>{const path="/azure-icons/"+file;const configured=assetUrl(path);return configured===path?"https://pub-a5e11688cacf4195a0d3c6afe384eb56.r2.dev"+path:configured};
function Icon({kind}:{kind:Kind}){const C=kind==="user"?Users:kind==="data"?Database:kind==="security"?Shield:kind==="network"?Network:kind==="storage"?HardDrive:kind==="ai"?BrainCircuit:kind==="monitor"?Activity:kind==="app"?Laptop:kind==="compute"?Server:kind==="file"?FileText:kind==="internet"?Globe2:Cloud;return <div className={"azure-node-icon azure-node-"+kind}><C size={28}/></div>}
function NodeView({node}:{node:Node}){const iconFile=iconFileFor(node.label);return <div className={"v8-node "+(node.kind?"public":"aws")}>{iconFile?<div className="azure-node-icon azure-node-ai"><img src={azureIconUrl(iconFile)} alt="" onError={(event)=>{event.currentTarget.style.display="none";const fallback=event.currentTarget.nextElementSibling as HTMLElement|null;if(fallback)fallback.style.display="block"}} /><Sparkles className="azure-icon-fallback" size={28}/></div>:node.kind?<Icon kind={node.kind}/>:<div className="azure-node-icon azure-node-ai"><Sparkles size={28}/></div>}<strong>{node.label}</strong><small>{node.sub}</small></div>}
function ArchitectureView({arch,index}:{arch:Architecture;index:number}){return <section className="v8-architecture azure-architecture" id={"azure-architecture-"+index}><div className="section-cap"><div><p>ARCHITECTURE {String(index).padStart(2,"0")}</p><h3>{arch.title}</h3></div><span>{arch.note}</span></div><div className="v8-reference">Reference pattern: {arch.reference}</div><div className="v8-layers">{arch.layers.map((layer,i)=><div className="v8-layer-wrap" key={layer.title}><div className="v8-layer"><b className="v8-layer-title">{layer.title}</b><div className="v8-layer-nodes">{layer.nodes.map((node,j)=><NodeView key={j} node={node}/>)}</div></div>{i<arch.layers.length-1&&<div className="v8-connector" aria-hidden="true">→</div>}</div>)}</div></section>}
function Cards({title,items,id}:{title:string;items:string[];id?:string}){return <section className="knowledge-card" id={id}><div className="knowledge-card-title"><span>◆</span><h3>{title}</h3></div><div className="knowledge-card-body"><div className="concept-stack">{items.map((item,i)=><p key={i}><b>{String(i+1).padStart(2,"0")}</b>{item}</p>)}</div></div></section>}
function Insight({title,icon,items}:{title:string;icon:string;items:string[]}){return <section className="service-insight-panel"><div className="service-panel-title"><span>{icon}</span><h3>{title}</h3></div><div className="service-insight-list">{items.map((item,i)=><div key={i}><b>{String(i+1).padStart(2,"0")}</b><p>{item}</p></div>)}</div></section>}
function CostBoard({items}:{items:string[]}){return <section className="service-cost-board"><div className="service-cost-cap"><div><p>COST MODEL</p><h3>How the bill behaves</h3></div><span>Estimate the service path, not only the central API.</span></div><div className="service-cost-grid">{items.map((item,i)=><article className={i===0?"recommended":""} key={i}><b>{String(i+1).padStart(2,"0")}</b><p>{item}</p></article>)}</div><div className="service-cost-rule"><b>Cost decision rule</b><span>Start with the documented billing unit, then include the resources and operations that make the workload possible.</span></div></section>}
function WalkthroughPlaceholder({service}:{service:string}){
  const [available,setAvailable]=useState(true);
  const [expanded,setExpanded]=useState(false);
  const [sourceIndex,setSourceIndex]=useState(0);
  const sources=azureWalkthroughUrls(service);
  const src=sources[sourceIndex];
  const handleSourceError=()=>{if(sourceIndex<sources.length-1)setSourceIndex(index=>index+1);else setAvailable(false)};
  return <section className="azure-walkthrough-placeholder" id="azure-service-walkthrough">
    <div className="azure-walkthrough-copy"><p>SERVICE WALKTHROUGH</p><h3>{service} console / portal walkthrough</h3><span>{available?"Open the step-by-step walkthrough in the page or full view.":"Upload the matching walkthrough image to azure-certification-walkthroughs to connect it automatically."}</span></div>
    {available?<button type="button" className="azure-walkthrough-preview" onClick={()=>setExpanded(true)}><img key={src} src={src} loading="lazy" decoding="async" alt={service+" console walkthrough"} onError={handleSourceError}/><span>Open full view</span></button>:<a href="#azure-service-walkthrough">Walkthrough coming soon</a>}
    {expanded&&available&&<div className="azure-walkthrough-modal" role="dialog" aria-modal="true" aria-label={service+" walkthrough full view"} onClick={()=>setExpanded(false)}><button type="button" className="azure-walkthrough-close" onClick={()=>setExpanded(false)}>Close ×</button><img src={src} alt={service+" console walkthrough full view"} onClick={event=>event.stopPropagation()}/></div>}
  </section>
}
export default function AzureServiceLearningDetails({serviceName}:{serviceName:string}){const detail=D[serviceName];if(!detail)return null;return <div className="service-knowledge aip-shared-learning aip-v8 azure-service-learning" data-service={serviceName}><div className="knowledge-intro"><div><p className="knowledge-kicker">VISUAL DEEP DIVE • {(detail.category||"AI + MACHINE LEARNING").toUpperCase()}</p><h2>{serviceName}</h2><p><b>What it is:</b> {detail.summary}</p></div><div className="knowledge-facts"><span><b>01</b>Purpose</span><span><b>02</b>Architecture</span><span><b>03</b>Operations</span><span><b>04</b>Exam fit</span></div></div><nav className="knowledge-jumps"><a href="#azure-concepts">Concepts</a><a href="#azure-architecture-1">Architectures</a><a href="#azure-service-walkthrough">Walkthrough</a><a href="#azure-security">Security</a><a href="#azure-cost">Cost</a><a href="#azure-hook">Exam hook</a></nav><div className="knowledge-grid aip-intro-grid" id="azure-concepts"><Cards title="Core service concepts" items={detail.concepts}/><Cards title="Application fit" items={detail.fit}/></div>{detail.architectures.map((arch,i)=><ArchitectureView key={i} arch={arch} index={i+1}/>)}<WalkthroughPlaceholder key={serviceName} service={serviceName}/><div className="service-insight-grid" id="azure-security"><Insight title="Security & governance" icon="◆" items={detail.security}/><Insight title="Design & optimization" icon="◇" items={detail.optimization}/><Insight title="Service-specific watch points" icon="!" items={detail.watch}/></div><div className="knowledge-grid azure-lower-grid"><CostBoard items={detail.cost}/><section className="knowledge-card aip-decision-card"><div className="knowledge-card-title"><span>◆</span><h3>Choose the right service</h3></div><p className="aip-decision-headline">Use the service whose native boundary matches the workload.</p><div className="aip-choice-grid">{detail.choices.map((choice,i)=><div className={"aip-choice "+(i===0?"current":"")} key={choice.name}><b>{choice.name}</b><span>{choice.when}</span></div>)}</div></section><Cards id="azure-hook" title="Certification memory hook" items={detail.hook}/></div></div>}
